// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title FileProcessingWorker
 * @notice Background job worker that processes user-uploaded content references
 * @dev Handles IPFS CID resolution and on-chain metadata storage
 */
contract FileProcessingWorker is Ownable, ReentrancyGuard {

    struct UploadJob {
        address submitter;
        bytes32 contentHash;
        string resolvedPath;
        uint256 timestamp;
        JobStatus status;
        uint8 retryCount;
    }

    enum JobStatus { Pending, Processing, Completed, Failed }

    mapping(uint256 => UploadJob) public jobs;
    mapping(address => uint256[]) public userJobs;
    mapping(bytes32 => bool) public processedHashes;
    mapping(address => bool) public authorizedWorkers;

    uint256 public jobCounter;
    uint256 public constant MAX_RETRIES = 3;
    uint256 public constant JOB_TIMEOUT = 1 hours;

    // Path resolution registry - maps symbolic references to actual storage paths
    mapping(bytes32 => bytes32) public pathLinks;
    mapping(bytes32 => address) public pathOwners;
    mapping(bytes32 => bool) public isSymbolicPath;

    event JobSubmitted(uint256 indexed jobId, address indexed submitter, bytes32 contentHash);
    event JobCompleted(uint256 indexed jobId, string resolvedPath);
    event JobFailed(uint256 indexed jobId, string reason);
    event PathLinked(bytes32 indexed source, bytes32 indexed target, address creator);

    modifier onlyWorker() {
        require(authorizedWorkers[msg.sender] || msg.sender == owner(), "Not authorized worker");
        _;
    }

    constructor() {
        authorizedWorkers[msg.sender] = true;
    }

    function addWorker(address worker) external onlyOwner {
        authorizedWorkers[worker] = true;
    }

    function removeWorker(address worker) external onlyOwner {
        authorizedWorkers[worker] = false;
    }

    /**
     * @notice Submit a new upload processing job
     * @param contentHash The hash of the uploaded content
     */
    function submitJob(bytes32 contentHash) external nonReentrant returns (uint256) {
        require(contentHash != bytes32(0), "Invalid content hash");
        require(!processedHashes[contentHash], "Already processed");

        uint256 jobId = jobCounter++;
        jobs[jobId] = UploadJob({
            submitter: msg.sender,
            contentHash: contentHash,
            resolvedPath: "",
            timestamp: block.timestamp,
            status: JobStatus.Pending,
            retryCount: 0
        });

        userJobs[msg.sender].push(jobId);
        emit JobSubmitted(jobId, msg.sender, contentHash);
        return jobId;
    }

    /**
     * @notice Create a symbolic path link (like a symlink in filesystem)
     * @param source The symbolic path identifier
     * @param target The target path identifier it resolves to
     */
    function createPathLink(bytes32 source, bytes32 target) external {
        require(source != bytes32(0) && target != bytes32(0), "Invalid path");
        require(pathOwners[source] == address(0) || pathOwners[source] == msg.sender, "Not path owner");

        pathLinks[source] = target;
        pathOwners[source] = msg.sender;
        isSymbolicPath[source] = true;

        emit PathLinked(source, target, msg.sender);
    }

    /**
     * @notice Resolve a path following symbolic links
     * @dev Follows chain of symbolic links to find final target
     * @param pathId The starting path identifier
     */
    function resolvePath(bytes32 pathId) public view returns (bytes32) {
        bytes32 current = pathId;
        uint8 depth = 0;

        // Follow symbolic links with depth limit
        while (isSymbolicPath[current] && depth < 10) {
            current = pathLinks[current];
            depth++;
        }

        return current;
    }

    /**
     * @notice Process a job by resolving its content path
     * @dev Worker resolves the content hash through path links and validates
     * @param jobId The job to process
     * @param basePath The base storage path for resolution
     */
    function processJob(uint256 jobId, bytes32 basePath) external onlyWorker nonReentrant {
        UploadJob storage job = jobs[jobId];
        require(job.status == JobStatus.Pending || job.status == JobStatus.Processing, "Job not processable");
        require(block.timestamp - job.timestamp < JOB_TIMEOUT, "Job timed out");

        job.status = JobStatus.Processing;

        // Resolve the content path through symbolic links
        bytes32 resolvedBase = resolvePath(basePath);
        bytes32 finalPath = keccak256(abi.encodePacked(resolvedBase, job.contentHash));

        // Validate the resolved path belongs to the submitter's namespace
        // BUG: validates against original basePath owner, not the RESOLVED path owner
        // An attacker can create a symlink chain: their_path -> victim_path
        // The ownership check passes (attacker owns the source symlink)
        // But the resolved path points to victim's storage namespace
        if (_validatePathAccess(basePath, job.submitter)) {
            job.resolvedPath = _bytes32ToString(finalPath);
            job.status = JobStatus.Completed;
            processedHashes[job.contentHash] = true;
            emit JobCompleted(jobId, job.resolvedPath);
        } else {
            job.retryCount++;
            if (job.retryCount >= MAX_RETRIES) {
                job.status = JobStatus.Failed;
                emit JobFailed(jobId, "Path access denied");
            } else {
                job.status = JobStatus.Pending;
            }
        }
    }

    /**
     * @notice Validate that a path is accessible by the given user
     * @param pathId The path to validate
     * @param user The user requesting access
     */
    function _validatePathAccess(bytes32 pathId, address user) internal view returns (bool) {
        // Check if user owns the path OR if path has no owner (public)
        address owner_ = pathOwners[pathId];
        return (owner_ == address(0) || owner_ == user);
    }

    /**
     * @notice Get the actual resolved owner of a path (follows symlinks)
     * @param pathId The path to check
     */
    function getResolvedPathOwner(bytes32 pathId) external view returns (address) {
        bytes32 resolved = resolvePath(pathId);
        return pathOwners[resolved];
    }

    function getJobDetails(uint256 jobId) external view returns (
        address submitter,
        bytes32 contentHash,
        string memory resolvedPath,
        uint256 timestamp,
        JobStatus status
    ) {
        UploadJob storage job = jobs[jobId];
        return (job.submitter, job.contentHash, job.resolvedPath, job.timestamp, job.status);
    }

    function getUserJobCount(address user) external view returns (uint256) {
        return userJobs[user].length;
    }

    function _bytes32ToString(bytes32 data) internal pure returns (string memory) {
        bytes memory bytesString = new bytes(64);
        for (uint256 i = 0; i < 32; i++) {
            bytes1 char = bytes1(bytes32(uint256(data) * 2 ** (8 * i)));
            bytesString[i * 2] = _toHexChar(uint8(char) / 16);
            bytesString[i * 2 + 1] = _toHexChar(uint8(char) % 16);
        }
        return string(bytesString);
    }

    function _toHexChar(uint8 value) internal pure returns (bytes1) {
        if (value < 10) return bytes1(value + 48);
        return bytes1(value + 87);
    }
}
